function collectBrandTokens(text){const brands=new Set();const urlRe=/https?:\/\/([^\s)\/]+)/gi;let m;while(m=urlRe.exec(text)){const host=m[1].replace(/^www\./i,'');for(const part of host.split('.')){if(part.length>2&&!/^(ru|com|net|org|io|kz|by|ua|tr|de|uk|me|app|dev|info|biz)$/i.test(part))brands.add(part.toLowerCase());}}const bareRe=/\b([a-z0-9][a-z0-9-]{1,})\.(?:ru|com|net|org|io|kz|by|ua|tr|de|uk|me|app|dev|cloud|online|store|site|info|biz)\b/gi;while(m=bareRe.exec(text))brands.add(m[1].toLowerCase());return brands;}// Возвращает { hard:[…], soft:[…] } — термины с русским эквивалентом и прочая латиница.
