function extractMdTableByHeading(fullText,headingRe){const lines=String(fullText||'').split('\n');let heading='';for(let i=0;i<lines.length;i++){const t=lines[i].trim();if(/^#{1,6}\s+/.test(t)){heading=t.replace(/^#+\s*/,'').trim();continue;}if(/^BLOCK\s/i.test(t)||/^SEO-\d/i.test(t)){heading=t.replace(/\s*[:—-]\s*$/,'').trim();continue;}if(t.startsWith('|')&&i+1<lines.length&&isMdSeparator(lines[i+1].trim())){const headers=splitMdRow(t);const rows=[];let j=i+2;for(;j<lines.length;j++){const rt=lines[j].trim();if(!rt.startsWith('|'))break;const cells=splitMdRow(rt);const obj={};headers.forEach((h,k)=>{if(h)obj[h]=cells[k]===undefined?'':cells[k];});rows.push(obj);}if(headingRe.test(heading))return{headers,rows,dataStart:i+2,dataEnd:j};i=j-1;}}return null;}// Пересобирает ТОЛЬКО строки данных (шапка/разделитель не трогаются) — используется
