function extractSection(fullText,headingRe){const lines=String(fullText||'').split('\n');let start=-1;for(let i=0;i<lines.length;i++){if(headingRe.test(lines[i].trim())){start=i;break;}}if(start<0)return'';let end=lines.length;for(let i=start+1;i<lines.length;i++){if(/^#{1,6}\s+/.test(lines[i].trim())){end=i;break;}}return lines.slice(start,end).join('\n').trim();}const normalizeQuote=s=>String(s||'').replace(/\s+/g,' ').trim();// Отбрасывает строки, чья нормализованная-в-нижний-регистр цитата уже встречалась
