function hashDedupe(rows,quoteField){const seen=new Set();return rows.filter(row=>{const key=normalizeQuote(row[quoteField]).toLowerCase();if(!key||seen.has(key))return false;seen.add(key);return true;});}// Итоговый блок покрытия VoC по сегментам — приклеивается КОДОМ после ответа модели
