const comparable=(()=>{if(!m2Result||!m2Result.content)return null;const t06=(parseMdTables(m2Result.content)||[]).find(t=>/BLOCK\s*06(?!_1|_2|_3|B)\b/i.test(t.heading||''));if(!t06||!t06.rows.length)return null;const keys=Object.keys(t06.rows[0]);const cmpKey=keys.find(k=>k.toLowerCase().includes('сопостав'));const nameKey=keys.find(k=>k.toLowerCase().includes('назван'));if(!cmpKey||!nameKey)return null;const set=new Set();for(const r of t06.rows){if(/сравним/i.test(String(r[cmpKey]||''))){const nm=String(r[nameKey]||'').replace(/\*\*|\[|\]/g,'').trim().toLowerCase();if(nm)set.add(nm);}}return set.size?set:null;})();const isComparable=n=>!comparable||comparable.has(String(n).trim().toLowerCase());// Путь 1 — машиночитаемая карта конкурентов из CHART DATA, надёжнее разбора таблицы
