async function discoverNicheDomains(brief){const market=brief.geoMarket||brief.geoCompany||'';const product=brief.niche||brief.name||'';const niches=(brief.selectedNiche||'').split(',').map(s=>s.trim()).filter(Boolean);const topic=niches.length?niches[0]:product;const queries=[topic+' '+market+' форум обсуждение',topic+' '+market+' отзывы площадка',topic+' '+market+' вопрос ответ'];const evidence=await gatherEvidence(queries,3,5,{maxItems:20});const domains=new Set();for(const e of evidence){try{domains.add(new URL(e.url).hostname.replace(/^www\./,''));}catch{}}return[...domains];}// Реестр площадок для ниши — GET существующего (переиспользуем, ТЗ: «строится один
