const GEO_REGIONS=[{id:'225',name:'Россия целиком',pop:1.000},{id:'1',name:'Москва и область',pop:0.149},{id:'10174',name:'Санкт-Петербург и область',pop:0.051},{id:'11162',name:'Свердловская область',pop:0.029},{id:'11316',name:'Новосибирская область',pop:0.019},{id:'10995',name:'Краснодарский край',pop:0.040},{id:'11119',name:'Татарстан',pop:0.027}];// Спрос по регионам для подтверждённых владелицей фраз. Берём не все фразы, а
