async function fetchGeoDemand(brief,seeds){const market=brief.geoMarket||brief.geoCompany||'';// Только Россия: у Wordstat есть регионы, у Google Ads разрез другой и
// смешивать их нельзя (см. keywordSourceForMarket).
if(keywordSourceForMarket(market)!=='yandex')return null;const phrases=[...new Set(seeds||[])].filter(Boolean).slice(0,3);if(!phrases.length)return null;const rows=[];for(const r of GEO_REGIONS){let total=0,got=false;for(const ph of phrases){const d=await callWordstat(ph,{numPhrases:1,regions:[r.id]});if(d&&d.totalCount){total+=d.totalCount;got=true;}}rows.push({...r,count:got?total:null});}return rows.some(x=>x.count!=null)?{rows,phrases}:null;}// Проверка вменяемости кодов регионов. Регион не может искать больше, чем вся
