for(const имя of comps.slice(0,5)){queries.push(имя+' обзор блогер '+market);queries.push(имя+' отзыв эксперта telegram');queries.push('рекомендую '+имя+' '+market);queries.push(имя+' интеграция реклама у блогера');queries.push('сравнение '+имя+' '+(product||'')+' обзор');}// Кого аудитория читает, КРОМЕ самих продавцов: блогеры, эксперты,
// сообщества. Владелица 17.09: «какие популярные блогеры в этой нише —
