const ЦЕНЫ_МАКС_ИГРОКОВ=16;// потолок обращений: за каждый поиск платим
const СХЕМА_ЦЕН={type:'object',additionalProperties:false,required:['цены'],properties:{цены:{type:'array',items:{type:'object',additionalProperties:false,required:['название','от','валюта','период','url'],properties:{название:{type:'string',description:'Ровно как в присланном списке'},от:{type:['number','null'],description:'Младший ПЛАТНЫЙ тариф числом. Бесплатный тариф и «по запросу» — null'},валюта:{type:'string',enum:['RUB','USD','EUR','нет данных']},период:{type:'string',enum:['в месяц','в год','разово','за пользователя в месяц','нет данных']},url:{type:'string',description:'Адрес страницы, где цена написана'}}}}}};async function замерЦенСтрогое(д,brief){const кон=(д.конкуренты||[]).filter(к=>к&&!к.мы&&/[a-z0-9-]+\.[a-z]{2,}/i.test(String(к.сайт||'')));if(!кон.length)return д;const цели=кон.slice(0,ЦЕНЫ_МАКС_ИГРОКОВ);const куски=[];for(const к of цели){const домен=String(к.сайт).replace(/^https?:\/\//,'').replace(/\/.*$/,'');// Ищем ТОЛЬКО на его сайте: цена с чужой страницы — это чужая цена.
const найдено=await callSearch('тарифы стоимость цена подписка '+домен,{include_domains:[домен],max_results:3,search_depth:'advanced'});(найдено||[]).forEach(р=>куски.push('### '+к.название+' — '+(р.url||'')+'\n'+String(р.content||'').slice(0,900)));}if(!куски.length)return д;let разбор=null;try{const сырое=await callGPTСхема('Ты читаешь куски страниц с тарифами и выписываешь цены. Ничего не додумываешь: '+'нет числа в тексте — ставишь null. Бесплатный тариф ценой не считается — нужен '+'МЛАДШИЙ ПЛАТНЫЙ. «От 990 ₽ в месяц при оплате за год» — это 990, период «в месяц».','Игроки: '+цели.map(к=>к.название).join(', ')+'\n\nКуски страниц:\n\n'+куски.join('\n\n'),СХЕМА_ЦЕН,'prices');разбор=JSON.parse(сырое);}catch(e){return д;}const поИмени=new Map();((разбор||{}).цены||[]).forEach(ц=>{if(ц&&ц.название&&ц.от!=null&&ц.от>0){поИмени.set(String(ц.название).toLowerCase().trim(),ц);}});if(!поИмени.size)return{...д,замерЦен:{нет:true,искали:цели.length}};const конкуренты=(д.конкуренты||[]).map(к=>{const н=поИмени.get(String(к.название||'').toLowerCase().trim());if(!н)return к;// Свой замер сильнее ответа модели: у неё цены не было вовсе либо она
// назвала её «не опубликованной», глядя мимо страницы тарифов.
return{...к,цена:{от:н.от,до:к.цена&&к.цена.до||null,валюта:н.валюта,период:н.период,как_узнали:н.url||к.цена&&к.цена.как_узнали||''}};});return{...д,конкуренты,замерЦен:{нашли:поИмени.size,искали:цели.length}};}// Известность конкурентов — ЗАМЕР брендового спроса, а не оценка модели
// (решение владелицы 10.09). В текстовом пути это делает processM3Fame поверх
// markdown-таблицы; строгий путь текста не производит, и 16.09 замер пропал
// вместе с кольцом доли внимания. Здесь то же самое, но по строгим данным.
async function замерИзвестностиСтрогое(д,brief){const кон=(д.конкуренты||[]).filter(к=>к&&String(к.название||'').trim());if(!кон.length)return д;const есть=к=>/[a-z0-9-]+\.[a-z]{2,}/i.test(String(к.сайт||''));const замер=new Map();let вызовов=0,безСайта=0;for(const к of кон){const имя=cleanCompName(к.название);if(!имя||замер.has(имя))continue;// «Делают сами», «внутренний отдел» — не бренды: искать их бессмысленно.
if(!есть(к)){безСайта++;continue;}if(вызовов>=FAME_MAX_CALLS)break;вызовов++;const n=await callBrandDemand(имя,brief);if(n!=null)замер.set(имя,n);}// Имена, по которым замер не дал числа: без них человек видит «замерено 4»
// и не понимает, куда делись остальные (владелица 17.09).
const безСпроса=[];for(const к of кон){const имя=cleanCompName(к.название);if(имя&&есть(к)&&!замер.has(имя)&&!безСпроса.includes(имя))безСпроса.push(имя);}const всегоИмён=new Set(кон.map(к=>cleanCompName(к.название)).filter(Boolean)).size;if(!замер.size)return{...д,замерИзвестности:{нет:true,безСайта,всегоИмён,безСпроса}};const верх=Math.max(...замер.values());const уровень=n=>n<FAME_FLOOR||n<верх*FAME_NOTABLE_SHARE?'нишевый-малый':n>=верх*FAME_LEADER_SHARE?'лидер':'заметный';const конкуренты=кон.map(к=>{const n=замер.get(cleanCompName(к.название));return n==null?{...к,известность:'не замерено'}:{...к,известность:уровень(n),спрос:n};});const всего=[...замер.values()].reduce((a,b)=>a+b,0);const лидер=[...замер.entries()].sort((a,b)=>b[1]-a[1])[0];const источник=keywordSourceForMarket(brief.geoMarket||brief.geoCompany||'')==='yandex'?'Яндекс Wordstat':'Google Ads Keyword Planner';return{...д,конкуренты,замерИзвестности:{всего:замер.size,безСайта,верх,источник,всегоИмён,безСпроса,лидер:{имя:лидер[0],спрос:лидер[1]},доли:[...замер.entries()].sort((a,b)=>b[1]-a[1]).map(([имя,n])=>[имя,всего?+(n/всего*100).toFixed(1):0,n])}};}// ── Строгая схема разведки ниш (M2) ───────────────────────────────────────
