const REPORT_FIX_CSS="\n/* ── Поздние правки: идут ПОСЛЕ всех остальных листов ────────────────────\n   Имена .nprof, .sigrow, .rkey-side объявлены в нескольких константах, и\n   правка в ранней из них молча проигрывает поздней. Всё новое — здесь. */\n.nprof{display:grid;grid-template-columns:repeat(auto-fit,minmax(360px,1fr));gap:12px}\n/* Шапка карточки: фигура слева, имя, балл и вердикт справа; разбор — ниже\n   во всю ширину (владелица 16.09). */\n.ncard2{display:block;padding:14px 16px}\n.ncard2 .nhd{display:grid;grid-template-columns:112px minmax(0,1fr);gap:14px;align-items:center}\n.ncard2 .nhd>div:first-child{display:flex;justify-content:center}\n.ncard2 .nh b{font-size:14px;line-height:1.25}\n.ncard2 .tot{margin:6px 0 7px}\n.ncard2 .sigrows{margin-top:10px;padding-top:10px;border-top:1px solid var(--line-2)}\n.ncard2 .ntake{margin-top:10px;padding:6px 12px;font-size:11.5px}\n.ncard2 .nh b{font-size:13.5px}\n.ncard2 .tot i{font-size:22px}\n.ncard2 .sigrow .v3{font-size:12px;line-height:1.45}\n.ncard2.on{box-shadow:0 0 0 2px var(--mid), 0 18px 34px -20px rgba(45,36,22,.4)}\n.ncard2 .sigrow{display:block;padding:8px 0;grid-template-columns:none}\n.ncard2 .sigrow .k2{display:block;margin-bottom:3px}\n.ncard2 .sigrow .v3{display:block;overflow-wrap:anywhere}\n/* Ключ «как читать»: фигура слева, пояснения справа. */\n.rkey-side{display:grid;grid-template-columns:256px minmax(0,1fr);gap:14px 20px;align-items:start;margin:0}\n.rkey-side>div:first-child{min-width:0;overflow:hidden}\n.rkey-side>div:first-child{grid-row:1 / span 3}\n.rkey-side .rtext{max-width:none;font-size:12.5px}\n@media (max-width:760px){.rkey-side{grid-template-columns:1fr}.rkey-side>div:first-child{grid-row:auto}}\n/* Сноска мельче основного текста и со звёздочкой: иначе пояснение сливается\n   с данными (владелица 16.09). */\n.note{font-size:11.5px}\n.note:not(.confleg):not(.nhint)::before{content:\"* \";color:var(--ink-3)}\n/* Полный список просмотренного — под своей кнопкой, а не простынёй. */\n.srcall{display:none}\n.srcall.on{display:flex}\n.srcall-btn{margin-top:10px;font-size:11.5px;color:var(--ink-2);background:none;border:0;padding:0;cursor:pointer;text-decoration:underline}\n/* География спроса в строгом пути: полоса объёма и плотность числом. */\n.geo{overflow-x:auto}\n.geo .th,.geo .tr{display:grid;grid-template-columns:minmax(140px,1.2fr) 170px 64px 78px minmax(0,1.4fr);gap:12px;align-items:center;min-width:660px}\n.geo .th{padding:0 0 8px;border-bottom:1px solid var(--line);font-size:10px;font-weight:700;letter-spacing:.07em;text-transform:uppercase;color:var(--ink-3)}\n.geo .tr{padding:9px 0;border-top:1px solid var(--line-2);font-size:12.5px;color:var(--ink-2)}\n.geo .nm{font-size:13px;font-weight:700;color:var(--ink)}\n.geo .gvol{display:flex;align-items:center;gap:9px}\n.geo .rail{flex:1;height:14px;background:var(--line-2);border-radius:0;overflow:hidden}\n.geo .rail .b{display:block;height:14px;background:var(--mid)}\n.geo .v{font-variant-numeric:tabular-nums;white-space:nowrap}\n.geo .hi{color:var(--acc-strong-ink);font-weight:700}\n.geo .lo{color:var(--ink-3)}\n/* Карточка канала: подписи и значения — своей колонкой слева направо,\n   без наложения на описание (владелица 16.09). */\n.chn .c .cf{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px 18px;align-items:start;margin-top:10px;padding-top:10px;border-top:1px solid var(--line-2)}\n.chn .c .cf div{text-align:left;min-width:0}\n.chn .c .cf div span{display:block;margin-bottom:3px}\n.chn .c .cf div b{display:block;font-weight:600;color:var(--ink-2);overflow-wrap:anywhere}\n.chn .c .cf .r{text-align:left}\n/* Адрес канала в разборе своих площадок: отдельной строкой под именем и\n   кликабельный — раньше он налезал на соседнее поле (владелица 16.09). */\n.aud .a .who{display:flex;flex-direction:column;gap:3px;align-items:flex-start;min-width:0}\n.aud .a .who .whoname{display:flex;align-items:center}\n.aud .a .who .chlink{font-size:11.5px;color:var(--ink-2);overflow-wrap:anywhere;text-decoration:underline}\n.aud .a .who span{font-size:11.5px;color:var(--ink-3);overflow-wrap:anywhere}\n/* Сравнение каналов: решётка с полосами-долями от лучшего в столбце. */\n.chncmp{overflow-x:auto}\n.chncmp .th,.chncmp .tr{display:grid;grid-template-columns:minmax(150px,1.3fr) repeat(4,minmax(120px,1fr));gap:14px;align-items:center;min-width:700px}\n.chncmp .th{padding:0 0 8px;border-bottom:1px solid var(--line);font-size:10px;font-weight:700;letter-spacing:.07em;text-transform:uppercase;color:var(--ink-3)}\n.chncmp .tr{padding:10px 0;border-top:1px solid var(--line-2);font-size:12.5px;color:var(--ink-2)}\n.chncmp .tr.mine{background:color-mix(in srgb, var(--mid) 7%, transparent)}\n.chncmp .nm{font-size:13px;font-weight:700;color:var(--ink);line-height:1.25}\n.chncmp .nm i{display:block;font-style:normal;font-size:11px;font-weight:400;color:var(--ink-3)}\n.chncmp .cmpv{display:flex;align-items:center;gap:8px;min-width:0}\n.chncmp .cmpv .rail{flex:1;height:14px;background:var(--line-2);overflow:hidden}\n.chncmp .cmpv .rail .b{display:block;height:14px;background:var(--mid)}\n.chncmp .cmpv .v{font-variant-numeric:tabular-nums;white-space:nowrap}\n.chncmp .cmpv.no{color:var(--ink-3);font-size:11.5px}\n/* Разбор ценности под карточкой оффера: четыре части и слабое место. */\n.offval{margin:10px 0 0;padding:14px 18px;border:1px solid var(--line);border-radius:14px;background:color-mix(in srgb, var(--ink) 2%, transparent)}\n.offval .ovh{font-size:10px;font-weight:700;letter-spacing:.07em;text-transform:uppercase;color:var(--ink-3);margin-bottom:10px}\n.offval .ovr,.offval .ovweak{display:grid;grid-template-columns:150px minmax(0,1fr);gap:6px 16px;padding:7px 0;border-top:1px solid var(--line-2);font-size:12.5px;line-height:1.5}\n.offval .ovr:first-of-type{border-top:0}\n.offval .ovr span,.offval .ovweak span{font-size:10px;font-weight:700;letter-spacing:.07em;text-transform:uppercase;color:var(--ink-3)}\n.offval .ovr b{font-weight:400;color:var(--ink-2)}\n.offval .ovweak{box-shadow:inset 3px 0 0 var(--acc-quiet);padding-left:12px;margin-top:8px}\n.offval .ovweak b{font-weight:600;color:var(--ink)}\n@media (max-width:640px){.offval .ovr,.offval .ovweak{grid-template-columns:1fr}}\n/* Декомпозиция цели: цепочка от трафика к деньгам, между ступенями —\n   конверсия или чек. */\n.decomp{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px}\n.decomp .dstep{border:1px solid var(--line);border-radius:14px;padding:14px 16px;background:color-mix(in srgb, var(--ink) 2%, transparent);position:relative}\n.decomp .dk{display:block;font-size:10px;font-weight:700;letter-spacing:.07em;text-transform:uppercase;color:var(--ink-3);margin-bottom:6px}\n.decomp .dv{display:block;font-size:17px;font-weight:700;color:var(--ink);line-height:1.25;overflow-wrap:anywhere}\n.decomp .dc{display:block;margin-top:8px;padding-top:8px;border-top:1px solid var(--line-2);font-size:11.5px;color:var(--ink-2)}\n/* «Где нам продвигаться» — решение модуля: карточка на площадку. */\n.plan{display:grid;grid-template-columns:repeat(auto-fit,minmax(360px,1fr));gap:12px}\n.plan .pcard{border:1px solid var(--line);border-radius:16px;padding:16px 18px;background:var(--card);position:relative;overflow:hidden;transition:box-shadow .4s ease, transform .4s cubic-bezier(.2,.8,.2,1)}\n.plan .pcard:hover{transform:translateY(-2px);box-shadow:0 18px 34px -20px rgba(45,36,22,.4)}\n.plan .ph{display:flex;align-items:baseline;gap:10px;flex-wrap:wrap;margin-bottom:8px}\n.plan .ph .pn{font-size:22px;font-weight:700;color:var(--mid);letter-spacing:-.03em;line-height:1}\n.plan .ph b{font-size:15px;font-weight:700;color:var(--ink)}\n.plan .pcard>p{margin:0 0 10px;font-size:13px;line-height:1.55;color:var(--ink-2)}\n.plan .pf{display:block;margin-top:8px;padding-top:8px;border-top:1px solid var(--line-2);font-size:12.5px;line-height:1.5}\n.plan .pf span{display:block;font-size:10px;font-weight:700;letter-spacing:.07em;text-transform:uppercase;color:var(--ink-3);margin-bottom:3px}\n.plan .pf b{font-weight:400;color:var(--ink-2)}\n/* Сводка стратегии: куда идём и что выкладываем — одной решёткой. */\n.plantbl{overflow-x:auto;margin-bottom:18px}\n.plantbl .th,.plantbl .tr{display:grid;grid-template-columns:34px minmax(120px,.9fr) minmax(180px,1.6fr) minmax(110px,.9fr) minmax(140px,1.1fr) 108px;gap:12px;align-items:start;min-width:760px}\n.plantbl .th{padding:0 0 8px;border-bottom:1px solid var(--line);font-size:10px;font-weight:700;letter-spacing:.07em;text-transform:uppercase;color:var(--ink-3)}\n.plantbl .tr{padding:11px 0;border-top:1px solid var(--line-2);font-size:12.5px;color:var(--ink-2);line-height:1.5}\n.plantbl .pn{font-weight:700;color:var(--mid);font-size:15px;line-height:1.2}\n.plantbl .nm{font-size:13px;font-weight:700;color:var(--ink);line-height:1.3}\n/* Позиционирование по шагам: цепочка, итоговая фраза крупно внизу. */\n.poswrap{display:flex;flex-direction:column;gap:12px}\n.poscard{border:1px solid var(--line);border-radius:18px;padding:18px 22px;background:var(--card)}\n.poscard .posh{display:flex;align-items:baseline;gap:10px;margin-bottom:12px}\n.poscard .posh .eb{font-size:10px;font-weight:700;letter-spacing:.07em;text-transform:uppercase;color:var(--ink-3)}\n.poscard .posh b{font-size:15px;font-weight:700;color:var(--ink)}\n.poscard .posline{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:10px}\n.poscard .posstep{padding:11px 13px;border-radius:12px;background:color-mix(in srgb, var(--ink) 3%, transparent)}\n.poscard .posstep span{display:block;font-size:10px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--ink-3);margin-bottom:5px}\n.poscard .posstep b{display:block;font-size:12.5px;font-weight:400;color:var(--ink-2);line-height:1.5}\n.poscard .posfin{margin-top:14px;padding:14px 16px;border-radius:14px;box-shadow:inset 3px 0 0 var(--mid);background:color-mix(in srgb, var(--mid) 6%, transparent)}\n.poscard .posfin span{display:block;font-size:10px;font-weight:700;letter-spacing:.07em;text-transform:uppercase;color:var(--ink-3);margin-bottom:6px}\n.poscard .posfin b{font-family:var(--serif);font-size:15px;font-weight:600;color:var(--ink);line-height:1.5}\n.poscard .posproof{margin-top:10px;font-size:11.5px;color:var(--ink-3);line-height:1.5}\n/* Панель разбора мягко проявляется при смене площадки. */\n.pinfo.pfade{animation:pfadein .28s ease}\n@keyframes pfadein{from{opacity:.35;transform:translateY(3px)}to{opacity:1;transform:none}}\n@media (prefers-reduced-motion:reduce){.plist .pbar i{transition:none}.pinfo.pfade{animation:none}}\n/* Части строки в комплекте площадок. */\n.plist .pnum{font-size:13px;font-weight:700;color:var(--mid);font-variant-numeric:tabular-nums}\n.plist .pname{font-size:13px;font-weight:700;color:var(--ink);line-height:1.25;overflow-wrap:anywhere;min-width:0}\n.plist .ppct{font-size:12.5px;color:var(--ink-2);font-variant-numeric:tabular-nums;text-align:right;white-space:nowrap}\n.pinfo .pih{display:flex;align-items:baseline;gap:10px;flex-wrap:wrap;margin-bottom:8px}\n\n/* Значки площадок — один язык на весь отчёт: контур цветом чернил, без\n   заливки и без цвета бренда (владелица 17.09). В листе отчёта есть общее\n   svg{display:block} — из-за него значок вставал НАД именем канала, поэтому\n   здесь он явно строчный. */\n.pico{display:inline-block;width:15px;height:15px;fill:none;stroke:var(--ink-2);\n  stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round;flex:0 0 auto;\n  vertical-align:-3px;margin-right:7px}\n.ci .pico{display:block;width:19px;height:19px;margin:0}\n.chncmp .nm .pico,.aud .a .who .pico{vertical-align:-3px}\n/* ── «Где нам продвигаться»: слева доли усилий, справа разбор ──────────\n   Свой префикс chp-: имена .prow/.pname уже заняты другой таблицей отчёта,\n   и её сетка ломала этот блок (владелица 17.09). */\n.chpviz{display:grid;grid-template-columns:minmax(260px,1fr) minmax(0,1.25fr);\n  gap:18px;align-items:start}\n.chplist{display:flex;flex-direction:column;gap:2px;min-width:0}\n.chprow{display:grid;grid-template-columns:22px minmax(110px,auto) minmax(60px,1fr) 46px;\n  gap:12px;align-items:center;width:100%;padding:9px 10px;border:0;border-radius:10px;\n  background:none;text-align:left;cursor:pointer;font:inherit;color:inherit;\n  transition:background .18s ease}\n.chprow:hover,.chprow.on{background:color-mix(in srgb, var(--ink) 4%, transparent)}\n.chprow.on{box-shadow:inset 2px 0 0 var(--mid)}\n.chpnum{font-size:12.5px;font-weight:700;color:var(--mid);font-variant-numeric:tabular-nums}\n.chpname{display:flex;align-items:center;font-size:13px;font-weight:700;color:var(--ink);\n  line-height:1.25;min-width:0;overflow-wrap:anywhere}\n.chpbar{display:block;height:14px;background:var(--line-2);overflow:hidden}\n.chpbar i{display:block;height:14px;background:var(--mid);transition:width .7s cubic-bezier(.2,.8,.2,1)}\n.chppct{font-size:12.5px;color:var(--ink-2);font-variant-numeric:tabular-nums;\n  text-align:right;white-space:nowrap}\n.chpinfo{border:1px solid var(--line);border-radius:16px;padding:16px 18px;\n  background:var(--card);min-width:0}\n.chpih{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:8px}\n.chpih b{display:inline-flex;align-items:center;font-size:15px;color:var(--ink);min-width:0}\n.chpwhy{margin:0 0 10px;font-size:13px;line-height:1.55;color:var(--ink-2)}\n.chpf{display:grid;grid-template-columns:132px minmax(0,1fr);gap:4px 14px;\n  padding:8px 0;border-top:1px solid var(--line-2);font-size:12.5px;line-height:1.5}\n.chpf span{font-size:10px;font-weight:700;letter-spacing:.07em;text-transform:uppercase;\n  color:var(--ink-3);padding-top:2px}\n.chpf b{font-weight:400;color:var(--ink-2);overflow-wrap:anywhere}\n.chpinfo.chpfade{animation:chpfadein .28s ease}\n@keyframes chpfadein{from{opacity:.35;transform:translateY(3px)}to{opacity:1;transform:none}}\n@media (prefers-reduced-motion:reduce){.chpbar i{transition:none}.chpinfo.chpfade{animation:none}}\n@media (max-width:820px){.chpviz{grid-template-columns:1fr}\n  .chpf{grid-template-columns:1fr}}\n/* Куда не идём: та же решётка, что у прочих таблиц блока. */\n.skipl{display:block}\n.skipl .th,.skipl .tr{display:grid;grid-template-columns:minmax(130px,.9fr) 132px minmax(0,1.7fr) minmax(0,1.4fr);\n  gap:10px 14px;align-items:start;padding:9px 2px}\n.skipl .th{font-size:10.5px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;\n  color:var(--ink-3);border-bottom:1px solid var(--line)}\n.skipl .tr{border-bottom:1px solid var(--line-2);font-size:12.5px;line-height:1.5}\n.skipl .tr:last-child{border-bottom:0}\n.skipl .nm{display:flex;align-items:center;font-weight:600}\n@media (max-width:760px){.skipl .th{display:none}\n  .skipl .tr{grid-template-columns:1fr;gap:4px}}\n/* Решение владельца по площадке: модуль советует, но берёт в работу человек. */\n.pltake{font:inherit;font-size:11.5px;font-weight:600;color:var(--ink-2);background:none;\n  border:1px solid var(--line);border-radius:999px;padding:5px 11px;cursor:pointer;\n  white-space:nowrap;transition:background .18s ease,color .18s ease,border-color .18s ease}\n.pltake:hover{border-color:var(--mid);color:var(--ink)}\n.pltake.on{background:color-mix(in srgb, var(--mid) 16%, transparent);border-color:var(--mid);color:var(--ink)}\n/* Решение и кнопка — в одной колонке: отдельный столбец под кнопку съедал\n   место у текста (владелица 17.09). */\n.skipl .skdec{display:flex;flex-direction:column;align-items:flex-start;gap:6px}\n.skipl .skdec .pltake{font-size:11px;padding:4px 10px}\n/* Примеры без замеров: список строками, не сноска. */\n.nomeas{display:block;margin-top:4px}\n.nmrow{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(120px,.7fr) minmax(0,1fr);\n  gap:10px 16px;align-items:baseline;padding:9px 2px;border-top:1px solid var(--line-2);\n  font-size:12.5px;line-height:1.5;color:var(--ink-2)}\n.nmrow:first-child{border-top:0}\n.nmname{font-weight:600;color:var(--ink);overflow-wrap:anywhere}\n.nmname a{color:var(--ink);text-decoration:underline;text-underline-offset:2px}\n.nmplat{display:flex;align-items:center;color:var(--ink-3)}\n.nmmeta{color:var(--ink-3);font-size:11.5px;overflow-wrap:anywhere}\n@media (max-width:760px){.nmrow{grid-template-columns:1fr;gap:3px}}\n/* Какой формат заходит: отдача по формату, полоса от лучшего. */\n.fmts{overflow-x:auto}\n.fmts .th,.fmts .tr{display:grid;grid-template-columns:minmax(120px,1fr) 96px 132px minmax(140px,1fr) minmax(0,1.2fr);\n  gap:14px;align-items:center;min-width:660px}\n.fmts .th{padding:0 0 8px;border-bottom:1px solid var(--line);font-size:10px;font-weight:700;\n  letter-spacing:.07em;text-transform:uppercase;color:var(--ink-3)}\n.fmts .tr{padding:10px 0;border-top:1px solid var(--line-2);font-size:12.5px;color:var(--ink-2)}\n.fmts .nm{font-size:13px;font-weight:700;color:var(--ink);text-transform:capitalize}\n.fmts .v{font-variant-numeric:tabular-nums;white-space:nowrap}\n.fmts .fmtb{display:flex;align-items:center;gap:8px;min-width:0}\n.fmts .fmtb .rail{flex:1;height:14px;background:var(--line-2);overflow:hidden}\n.fmts .fmtb .rail .b{display:block;height:14px;background:var(--mid)}\n.fmts .fmtb .no{color:var(--ink-3);font-size:11.5px}\n.fmts .fmtp{color:var(--ink-3);font-size:11.5px;overflow-wrap:anywhere}\n/* Сводка сбора: сколько чего принесли до работы модели. */\n.harvest{display:grid;grid-template-columns:repeat(auto-fit,minmax(132px,1fr));gap:10px;margin-bottom:10px}\n.harvest .hv{border:1px solid var(--line);border-radius:12px;padding:10px 12px;\n  background:color-mix(in srgb, var(--ink) 2%, transparent)}\n.harvest .hv b{display:block;font-size:19px;font-weight:700;color:var(--ink);\n  font-variant-numeric:tabular-nums;line-height:1.1}\n.harvest .hv span{display:block;margin-top:4px;font-size:10.5px;color:var(--ink-3);line-height:1.35}\n.harvest .hv.zero b{color:var(--ink-3)}\n/* Знак «здесь собираются персональные данные». Единственное место, где в\n   отчёте появляется красный: владелица 17.09 согласовала его отдельно —\n   «лишних цветов не хочу, но это должно отличаться от всего». Не для\n   украшения: знак говорит, что приём упирается в закон. */\n:root{--pd-red:#C0271F;--pd-red-soft:#FBEAE8}\n.pdwarn{display:inline-flex;align-items:center;justify-content:center;width:18px;height:18px;\n  margin-left:6px;border-radius:50%;background:var(--pd-red);color:#fff;\n  font-size:12px;font-weight:700;line-height:1;vertical-align:-3px;cursor:help;\n  flex:0 0 auto;font-family:var(--sans);box-shadow:0 0 0 3px var(--pd-red-soft)}\n.pdwarn:hover,.pdwarn:focus{outline:2px solid var(--pd-red);outline-offset:2px}\n@media (prefers-color-scheme:dark){:root{--pd-red-soft:rgba(192,39,31,.22)}}\n/* Кого читает аудитория: карточки голосов ниши. */\n.voices{display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:12px}\n.voices .vcard{border:1px solid var(--line);border-radius:16px;padding:14px 16px;\n  background:var(--card);min-width:0}\n.voices .vh{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:8px}\n.voices .vh b{font-size:13.5px;color:var(--ink);min-width:0;overflow-wrap:anywhere}\n.voices .vh b a{color:var(--ink);text-decoration:underline;text-underline-offset:2px}\n.voices .vkind{font-size:10px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;\n  color:var(--ink-3)}\n.voices .vsub{font-size:11.5px;color:var(--ink-3);font-variant-numeric:tabular-nums}\n.voices .vcard>p{margin:0 0 8px;font-size:12.5px;line-height:1.55;color:var(--ink-2)}\n.voices .vf{display:block;margin-top:8px;padding-top:8px;border-top:1px solid var(--line-2);\n  font-size:12.5px;line-height:1.5}\n.voices .vf span{display:block;font-size:10px;font-weight:700;letter-spacing:.07em;\n  text-transform:uppercase;color:var(--ink-3);margin-bottom:3px}\n.voices .vf b{font-weight:400;color:var(--ink-2);overflow-wrap:anywhere}\n.voices .vfmt{display:block;margin-top:3px;font-style:normal;font-size:11px;color:var(--ink-3)}\n/* Портреты аудитории: от них строится весь поиск радара. */\n.portraits{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:12px}\n.portraits .pcard2{border:1px solid var(--line);border-radius:16px;padding:14px 16px;\n  background:var(--card);min-width:0}\n.portraits .ph2{display:flex;align-items:baseline;gap:8px;flex-wrap:wrap;margin-bottom:8px}\n.portraits .ph2 b{font-size:13.5px;color:var(--ink)}\n.portraits .ph2 span{font-size:11.5px;color:var(--ink-3)}\n.portraits .pcard2>p{margin:0 0 8px;font-size:12.5px;line-height:1.55;color:var(--ink-2)}\n.portraits .pf{display:block;margin-top:8px;padding-top:8px;border-top:1px solid var(--line-2);\n  font-size:12.5px;line-height:1.5}\n.portraits .pf span{display:block;font-size:10px;font-weight:700;letter-spacing:.07em;\n  text-transform:uppercase;color:var(--ink-3);margin-bottom:3px}\n.portraits .pf b{font-weight:400;color:var(--ink-2);overflow-wrap:anywhere}\n/* Через кого узнают о конкурентах. */\n.reach{overflow-x:auto}\n.reach .th,.reach .tr{display:grid;grid-template-columns:minmax(150px,1.2fr) minmax(110px,.8fr) 170px 110px minmax(0,1.4fr);\n  gap:14px;align-items:start;min-width:760px}\n.reach .th{padding:0 0 8px;border-bottom:1px solid var(--line);font-size:10px;font-weight:700;\n  letter-spacing:.07em;text-transform:uppercase;color:var(--ink-3)}\n.reach .tr{padding:11px 0;border-top:1px solid var(--line-2);font-size:12.5px;\n  color:var(--ink-2);line-height:1.5}\n.reach .nm{display:flex;align-items:baseline;flex-wrap:wrap;font-size:13px;font-weight:700;color:var(--ink)}\n.reach .nm a{color:var(--ink);text-decoration:underline;text-underline-offset:2px}\n.reach .nm i{display:block;width:100%;font-style:normal;font-size:11px;font-weight:400;color:var(--ink-3)}\n.reach .reachw{display:block;margin-top:5px;font-style:normal;font-size:11.5px;color:var(--ink-3)}\n.reach .v{font-variant-numeric:tabular-nums;white-space:nowrap}\n/* Интересы аудитории частотностью. */\n.interests{display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:12px}\n.intgrp{border:1px solid var(--line);border-radius:16px;padding:14px 16px;background:var(--card)}\n.inth{display:flex;align-items:baseline;justify-content:space-between;gap:10px;\n  flex-wrap:wrap;margin-bottom:10px}\n.inth b{font-size:13.5px;color:var(--ink)}\n.inth span{font-size:10.5px;color:var(--ink-3)}\n.introw{display:grid;grid-template-columns:minmax(0,1fr) 84px 118px;gap:10px;align-items:center;\n  padding:7px 0;border-top:1px solid var(--line-2);font-size:12.5px}\n.introw:first-of-type{border-top:0}\n.intn{color:var(--ink-2);overflow-wrap:anywhere}\n.introw .rail{height:14px;background:var(--line-2);overflow:hidden}\n.introw .rail i{display:block;height:14px;background:var(--mid)}\n.intv{text-align:right;font-variant-numeric:tabular-nums;color:var(--ink);font-weight:600;\n  white-space:nowrap;font-size:12px}\n.intv.no{color:var(--ink-3);font-weight:400;font-size:11px}\n";const СХЕМА_M2={type:'object',additionalProperties:false,required:['источники','тип_бизнеса','квалификация','сегменты','ниши','итог'],properties:{источники:{type:'array',description:'ОДНА СТРОКА НА КАЖДУЮ выдержку, которой ты реально пользовался ниже. '+'Их обычно 15-30 — столько, сколько прислано в материалах. Восемь строк при '+'двадцати использованных выдержках — это потерянные источники, а не краткость',items:{type:'object',additionalProperties:false,required:['номер','площадка','url','что_взяли'],properties:{номер:{type:'integer'},площадка:строка('Имя площадки, человеческое'),url:строка('Полный адрес. Нет адреса — не включай источник вовсе'),что_взяли:строка('Что именно из него взято')}}},тип_бизнеса:{type:'object',additionalProperties:false,required:['вывод','почему'],properties:{вывод:{type:'string',enum:['услуги и есть ниши','функции одного продукта']},почему:строка('Одной фразой: почему так решил')}},квалификация:{type:'object',additionalProperties:false,required:['задана','критерий'],properties:{задана:{type:'boolean'},критерий:строка('Кого продукт может обслуживать — из брифа. Не задана — пустая строка')}},сегменты:{type:'array',description:'6-10 сегментов покупателей. Доли в сумме дают 100',items:{type:'object',additionalProperties:false,required:['сегмент','кто_это','потребность','доля_процентов','платёжеспособность','уверенность','проходит_квалификацию'],properties:{сегмент:строка('Короткое имя сегмента'),кто_это:строка('Одна строка: кто это'),потребность:строка('Ключевая потребность'),доля_процентов:{type:['number','null'],description:'Доля рынка сегмента, %. Нет данных — null, не выдумывай'},платёжеспособность:{type:'string',enum:['высокая','средняя','низкая','нет данных']},уверенность:{type:'integer',description:'От 1 до 5'},проходит_квалификацию:{type:'string',enum:['да','нет','квалификация не задана']}}}},ниши:{type:'array',description:'ВСЕ вертикали, какие нашлись, — обычно 10-25. Не только те, куда идём',items:{type:'object',additionalProperties:false,required:['ниша','спрос_сигналы','конкуренция_сигналы','экономика','риски','оценки','вердикт','почему_не_идём','рекомендуем','источники'],properties:{ниша:строка('Имя ниши — отрасль или сценарий спроса'),спрос_сигналы:строка('Что в собранном материале говорит о спросе'),конкуренция_сигналы:строка('Кто уже занят этой нишей'),экономика:строка('Чек × частота, как прикинули'),риски:строка('Чем опасна именно эта ниша'),оценки:{type:'object',additionalProperties:false,required:['спрос','конкуренция','экономика','соответствие'],properties:{спрос:{type:'integer',description:'1-5'},конкуренция:{type:'integer',description:'1-5, где 5 — конкурентов мало'},экономика:{type:'integer',description:'1-5'},соответствие:{type:'integer',description:'1-5: насколько продукт подходит нише'}}},вердикт:{type:'string',enum:['идём','под вопросом','не идём']},почему_не_идём:строка('Одной фразой, что закрывает нишу. У остальных — пустая строка'),рекомендуем:{type:'boolean',description:'true ровно у одной ниши — с которой начать'},источники:{type:'array',items:{type:'integer'},description:'Номера из списка источников'}}}},итог:{type:'object',additionalProperties:false,required:['что_узнали','что_это_значит','что_делаем'],properties:{что_узнали:{type:'array',items:{type:'string'}},что_это_значит:{type:'array',items:{type:'string'}},что_делаем:{type:'array',items:{type:'string'}}}}}};// ── Строгая схема контент-радара (M4) ─────────────────────────────────────
// Здесь конкуренты рассматриваются как МЕДИА: что публикуют, где, как часто и
// что у них залетает. Числа — только те, что видны на публичной странице.
