function нишиИзСтрогогоM2(д){const ниши=(д&&д.ниши||[]).filter(н=>н&&String(н.ниша||'').trim());if(!ниши.length)return null;return{niches:ниши.map(н=>{const о=н.оценки||{};return{name:н.ниша,demand:о.спрос||0,competition:о.конкуренция||0,economics:о.экономика||0,fit:о.соответствие||0,score:(о.спрос||0)+(о.конкуренция||0)+(о.экономика||0)+(о.соответствие||0),verdict:/не идём/i.test(н.вердикт||'')?'No-Go':/вопрос/i.test(н.вердикт||'')?'Maybe':'Go',why:н.почему_не_идём||н.спрос_сигналы||'',recommended:!!н.рекомендуем};}).sort((а,б)=>б.score-а.score)};}// Выжимка M2 для следующих модулей: они читают предыдущий как текст.
function текстИзСтрогогоM2(д){if(!д)return'';const ч=[];const стр=в=>String(в==null?'':в).replace(/\s+/g,' ').trim();const сег=(д.сегменты||[]).filter(с=>с&&стр(с.сегмент));if(сег.length){ч.push('## Сегменты аудитории\n');ч.push(сег.map(с=>'- '+стр(с.сегмент)+': '+стр(с.кто_это)+'. Потребность: '+стр(с.потребность)+(с.доля_процентов!=null?'. Доля: '+с.доля_процентов+'%':'')+'. Платёжеспособность: '+стр(с.платёжеспособность)).join('\n'));}const ниши=(д.ниши||[]).filter(н=>н&&стр(н.ниша));if(ниши.length){ч.push('\n## Приоритет ниш\n');ч.push(ниши.map(н=>{const о=н.оценки||{};return'- '+стр(н.ниша)+' — '+стр(н.вердикт)+' (спрос '+(о.спрос||0)+', конкуренция '+(о.конкуренция||0)+', экономика '+(о.экономика||0)+', соответствие '+(о.соответствие||0)+')'+(н.запросов?', замер: '+стр(н.запросов):'')+'. '+стр(н.спрос_сигналы);}).join('\n'));}const и=д.итог||{};if((и.что_узнали||[]).length||(и.что_делаем||[]).length){ч.push('\n## ИТОГ МОДУЛЯ\n');(и.что_узнали||[]).forEach(x=>ч.push('- Узнали: '+стр(x)));(и.что_это_значит||[]).forEach(x=>ч.push('- Значит: '+стр(x)));(и.что_делаем||[]).forEach(x=>ч.push('- Делаем: '+стр(x)));}return ч.join('\n');}// Служебные ссылки на блоки методологии («[04_0, строки 3–4]», «[04; 04_2]»)
// — это внутренняя нумерация промпта, человеку она ничего не говорит и
