async function метрикиVC(url){const ид=(String(url||'').match(/vc\.ru\/[^?#]*?(\d{5,9})(?:-|\/|$)/)||[])[1];if(!ид)return null;try{const r=await загрузитьСтраницу('https://api.vc.ru/v2.5/content?id='+ид);if(!r.ok)return null;const д=(await r.json()).result;if(!д||!д.title)return null;const с=д.counters||{};const автор=д.author&&д.author.name||'';const блог=д.subsite&&д.subsite.name||'';return{заголовок:д.title,url:д.url||url,площадка:'vc.ru',автор,блог,авторИд:д.author&&д.author.id!=null?д.author.id:null,дата:д.date?new Date(д.date*1000).toISOString().slice(0,10):'',просмотры:с.views!=null?с.views:null,реакции:(с.reactions||0)+(с.favorites||0),комментарии:с.comments!=null?с.comments:null};}catch(e){return null;}}// Свои статьи на vc.ru по ОДНОЙ ссылке. Владелица 17.09: аккаунт общий, там
