for(;;){const строки3=t.split('\n');const блок=найтиБлокАббревиатур(строки3);if(!блок)break;строки3.splice(блок.начало,блок.конец-блок.начало);t=строки3.join('\n');}// Расшифровки строкой, без заголовка-списка, — туда же, в подсказки.
