// поРусски, — иначе на сайте и в отчёте подписи разойдутся.
function поРусскиСтроку(t){let s2=String(t).replace(/\b[A-Za-z][A-Za-z ]{4,24}[A-Za-z]\b/g,фраза=>{const русская=ФРАЗЫ_РУ[фраза.toLowerCase().replace(/\s+/g,' ')];return русская||фраза;});return s2.replace(/\b([A-Za-z]{3,14})\b/g,слово=>{const русское=МЕТКИ_РУ[слово.toLowerCase()];if(!русское)return слово;return слово[0]===слово[0].toLowerCase()?русское.toLowerCase():русское;});}// Имя строки в таблице — с заглавной. Модель берёт их из промпта, где они
