function сБольшой(t){const с=String(t==null?'':t);const м=с.match(/^(\s*(?:\*\*)?)([а-яёa-z])/);return м?с.slice(0,м[1].length)+м[2].toUpperCase()+с.slice(м[1].length+1):с;}// Термины в тексте — с подсказкой. Объяснение всплывает там, где человек
