// по ней смотрят, где ты САМ относительно остальных. Ставим себя сами —
// имя из брифа, ценовой уровень из брифа, известность «не замерено».
if(!P.some(x=>x[4])&&ctx&&ctx.ourName){const наш=String(ctx.ourPrice||'').toLowerCase();const уровень=/vip|премиум/.test(наш)?3:/дорог/.test(наш)?2:/средн/.test(наш)?1:0;P.push([String(ctx.ourName),уровень,2,null,true]);}if(P.length<4)return null;// на трёх точках карта бессмысленна
