const словарьУровней=/^(да|нет|есть|отсут[а-яё]*|win|parity|lose|полн[а-яё]*|сильн[а-яё]*|частич[а-яё]*|средн[а-яё]*|слаб[а-яё]*|—|-|н\/д)$/i;const оценочная=h=>{const значения=rows.map(r=>String(r[h]||'').trim()).filter(Boolean);if(!значения.length)return false;const похожих=значения.filter(v=>словарьУровней.test(v.split(/[(,;·]/)[0].trim())).length;return похожих/значения.length>=0.7;};const comps=кандидаты.filter(оценочная);// Форма «Критерий | наше | лучшее у них | статус Win/Parity/Lose» — самая
// частая у гэп-анализа, и оценочная колонка в ней ровно одна. Прежнее
// требование двух отправляло её в сырую широкую таблицу на шесть колонок,
// которую приходилось листать вбок (владелица 15.09: «таблицы сломались,
// мы же специально делали другой формат»). Такой случай рисуем карточками
