function renderGuardrailsBlock(headers,rows){const kR=col(headers,'правило','что нельзя','ограничен');if(!kR)return null;const kW=col(headers,'на основании','почему','из чего');const D=rows.map(r=>{const t=String(r[kR]||'').replace(/\*\*/g,'').trim();if(!t)return null;const why=kW?String(r[kW]||'').trim():'';return why?t+' — '+why:t;}).filter(Boolean);if(!D.length)return null;blockScripts.push('renderGuardrails('+safeJson(D)+');');return'<div class="rules" id="rpt-rules"></div>';}// ── BLOCK 23 таблица 1: главная ставка карточками ───────────────────────────
// Пять элементов, каждый одной фразой, и читают их по одному, а не сравнивают
