// отдельно.
const разобратьСсылку=т=>{const с=String(т||'').trim();const м=с.match(/\[([^\]]*)\]\(([^)]+)\)/);if(м)return{номер:(м[1].match(/\d{1,3}/)||[''])[0],адрес:м[2].trim()};const адрес=(с.match(/https?:\/\/\S+/)||[''])[0].replace(/[),.]+$/,'');return{номер:(с.replace(/https?:\/\/\S+/,'').match(/\d{1,3}/)||[''])[0],адрес};};// «Не замерено» дважды подряд («не замерено · не замерено») — это не
