function renderTacticsBlock(headers,rows){const kT=col(headers,'тактик');if(!kT)return null;const kP=col(headers,'принцип'),kA=col(headers,'артефакт','инструмент'),kR=col(headers,'риск'),kE=col(headers,'пример'),kM=col(headers,'метрик'),kPer=col(headers,'персона');const g=(r,k)=>k?String(r[k]||'').replace(/\*\*/g,'').trim():'';const d=rows.map(r=>{const t=g(r,kT);if(!t)return null;return[t,g(r,kP),g(r,kE),g(r,kR),[g(r,kPer),g(r,kA),g(r,kM)].filter(x=>x&&x!=='—').join(' · ')];}).filter(Boolean);if(!d.length)return null;blockScripts.push('renderTactics('+safeJson(d)+');');return'<div class="rules" id="rpt-tactics"></div>';}// ── BLOCK 06_3: позиционирование по сегментам ───────────────────────────────
// На каждый сегмент — своя формулировка: в какой категории нас понимают,
