function renderArchetypeBlock(headers,rows){const kA=col(headers,'архетип');if(!kA)return null;const kR=col(headers,'роль'),kW=col(headers,'почему'),kT=col(headers,'занят','соперник','конкурент'),kX=col(headers,'риск');const g=(r,k)=>k?String(r[k]||'').replace(/\*\*/g,'').trim():'';const d=rows.map(r=>{const a=g(r,kA);if(!a||/^—$/.test(a))return null;return[a,g(r,kR),g(r,kW),g(r,kT),g(r,kX)];}).filter(Boolean);if(!d.length)return null;blockScripts.push('renderArchetype('+safeJson(d)+');');return'<div class="rules bet" id="rpt-arch"></div>';}// Таблица «как это проявляется»: элемент, в чём выражается, живой пример и
