function renderManifestBlock(headers,rows){const kЭ=col(headers,'элемент','приём','правило','параметр');const kП=col(headers,'как проявляется','проявлен','в чём','описан');if(!kЭ||!kП)return null;const kПр=col(headers,'пример','формулировк'),kН=col(headers,'избега','нельзя','запрещ');const g=(r,k)=>k?String(r[k]||'').replace(/\*\*/g,'').trim():'';const D=rows.map(r=>{const э=g(r,kЭ);if(!э||э==='—')return null;return[э,g(r,kП),g(r,kПр),g(r,kН)];}).filter(Boolean);if(D.length<2)return null;blockScripts.push('renderManifest('+safeJson(D)+');');return'<div class="rules" id="rpt-manif"></div>';}// Последняя попытка перед сырой таблицей: разбор «в нашем стиле» для любой
// таблицы-перечня — имя строки слева, содержимое под ним. Владелица 15.09
// прошла по М3 и назвала шесть таких мест подряд: «куда расти», «главное
// обещание», «три главных приоритета», «что отложить», «какие данные нужны»,
// «ориентиры рынка». У каждой свой заголовок, который модель придумывает
// заново, — гоняться за ними по именам бессмысленно.
//
// Не трогаем то, что действительно таблица: где есть числовые колонки, их
